    @Override
    public Set<String> supportedFileAttributeViews() {
      return Collections.emptySet();
    }

    @Override
    public Path getPath(String first, String... more) {
      throw new UnsupportedOperationException();
    }

    @Override
    public PathMatcher getPathMatcher(String syntaxAndPattern) {
      throw new UnsupportedOperationException();
    }

    @Override
    public UserPrincipalLookupService getUserPrincipalLookupService() {
      throw new UnsupportedOperationException();
    }

    @Override
    public WatchService newWatchService() throws IOException {
      throw new UnsupportedOperationException();
    }
  }

  @Test
  void compareToOrdersPathsByStringRepresentation() {
    FileSystem fs = new StubFileSystem();
    SingleEntryArchivePath a = new SingleEntryArchivePath(fs, SingleEntryArchiveFormat.GZIP, false, "a");
    SingleEntryArchivePath b = new SingleEntryArchivePath(fs, SingleEntryArchiveFormat.GZIP, false, "b");
    SingleEntryArchivePath a2 = new SingleEntryArchivePath(fs, SingleEntryArchiveFormat.GZIP, false, "a");

    assertTrue(a.compareTo(b) < 0);
    assertTrue(b.compareTo(a) > 0);
    assertEquals(0, a.compareTo(a2));
